  IF NEW.status NOT IN ('draft','submitted') THEN RAISE EXCEPTION 'workflow: % must be created at draft or submitted', TG_TABLE_NAME USING ERRCODE='insufficient_privilege'; END IF;
  IF NEW.verified_by_user_id IS NOT NULL OR NEW.approved_by_user_id IS NOT NULL OR NEW.issued_by_user_id IS NOT NULL OR NEW.issued_at IS NOT NULL THEN RAISE EXCEPTION 'workflow: actor/issuance fields are set by transitions only'; END IF;
