IF NEW.status = 'verified' AND OLD.status <> 'verified' AND (NEW.verified_by_user_id IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'workflow: verifier must be the caller'; END IF;
IF NEW.status = 'approved' AND OLD.status <> 'approved' THEN
  IF NEW.approved_by_user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'workflow: approver must be the caller'; END IF;
