CREATE FUNCTION pin_credential_request_subject() RETURNS trigger AS $$ BEGIN
 IF OLD.status NOT IN ('draft','submitted','under_review','returned') AND (NEW.resident_id,NEW.request_type,NEW.credential_type,NEW.issuing_kebele_id) IS DISTINCT FROM (OLD.resident_id,OLD.request_type,OLD.credential_type,OLD.issuing_kebele_id) THEN
  RAISE EXCEPTION 'credential_request: subject fields are frozen after verification'; END IF; RETURN NEW; END $$ LANGUAGE plpgsql;

DROP POLICY credential_request_update ON public.credential_request;
CREATE POLICY credential_request_update ON public.credential_request FOR UPDATE TO authenticated
 USING (woreda_id = get_user_woreda_id() AND user_has_any_perm(ARRAY['credential.submit','credential.review','credential.resubmit','credential.return','credential.reject','credential.approve','credential.record_payment','credential.confirm_print','credential.activate']))
 WITH CHECK (same);

UPDATE public.residence_credential SET status='revoked', revoked_at=now(), revoked_reason=v_reason
 WHERE resident_id=NEW.resident_id AND woreda_id=NEW.woreda_id AND status IN ('ready_to_print','printing','printed','active','suspended');
